CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, full_name VARCHAR(150) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, language VARCHAR(10) NOT NULL DEFAULT 'vi', created_at TIMESTAMP NOT NULL DEFAULT (now() at time zone 'utc'), updated_at TIMESTAMP NOT NULL DEFAULT (now() at time zone 'utc'));
CREATE TABLE roles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, CONSTRAINT pk_user_roles PRIMARY KEY(user_id, role_id), CONSTRAINT fk_ur_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_ur_role FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, description TEXT, price DECIMAL(18,2) NOT NULL, thumbnail_url VARCHAR(500), status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT (now() at time zone 'utc'), updated_at TIMESTAMP NOT NULL DEFAULT (now() at time zone 'utc'));
CREATE TABLE locations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, description TEXT, image_url VARCHAR(500));
CREATE TABLE stories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, location_id BIGINT NULL, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, summary VARCHAR(1000), content TEXT, category VARCHAR(50), cover_image VARCHAR(500), reading_time INT, created_at TIMESTAMP NOT NULL DEFAULT (now() at time zone 'utc'), CONSTRAINT fk_story_location FOREIGN KEY(location_id) REFERENCES locations(id));
CREATE TABLE digital_passports (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, total_points INT NOT NULL DEFAULT 0, level INT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT (now() at time zone 'utc'), updated_at TIMESTAMP NOT NULL DEFAULT (now() at time zone 'utc'), CONSTRAINT fk_passport_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE qr_tokens (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, token VARCHAR(255) NOT NULL UNIQUE, product_id BIGINT NULL, status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT (now() at time zone 'utc'), used_at TIMESTAMP NULL, expires_at TIMESTAMP NULL, CONSTRAINT fk_qr_product FOREIGN KEY(product_id) REFERENCES products(id));
